package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.jscomp.phases.NodeTraversal;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.powermock.api.mockito.PowerMockito;
import org.powermock.core.classloader.annotations.PrepareForTest;
import org.powermock.modules.junit4.PowerMockRunner;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(PowerMockRunner.class)
@PrepareForTest({CheckGlobalThis.class})
public class CheckGlobalThis_visit_TriageGen2Test {

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private CompilerError error;

    private CheckGlobalThis checkGlobalThis;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Since we cannot easily instantiate the real object if it has private/protected dependencies
        // we assume the class is testable or we use a spy/mock approach for the internal state.
        checkGlobalThis = new CheckGlobalThis(compiler);
    }

    /**
     * Test Case 1: n.getType() is NOT Token.THIS and n is NOT assignLhsChild.
     * Covers: skip both if blocks.
     */
    @Test
    public void testVisit_NoConditionsMet() {
        when(n.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(t, n, parent);

        // Verify no error reported and no state change (implicitly)
    }

    /**
     * Test Case 2: n.getType() is Token.THIS, but shouldReportThis is false, and n is NOT assignLhsChild.
     * Covers: first if fails, second if fails.
     */
    @Test
    public void testVisit_ThisButShouldNotReport() {
        when(n.getType()).thenReturn(Token.THIS);
        // We need to mock/spy the method shouldReportThis which is in the same class.
        // For this purpose, we assume CheckGlobalThis is a spy or we use a subclass to override.
        CheckGlobalThis spyCheck = PowerMockito.spy(checkGlobalThis);
        PowerMockito.doReturn(false).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler, org.mockito.Mockito.never()).report(any());
    }

    /**
     * Test Case 3: n.getType() is Token.THIS, shouldReportThis is true, and n is NOT assignLhsChild.
     * Covers: first if succeeds (reports error), second if fails.
     */
    @Test
    public void testVisit_ReportGlobalThis() {
        when(n.getType()).thenReturn(Token.THIS);
        when(t.makeError(n, any(), any())).thenReturn(error);

        CheckGlobalThis spyCheck = PowerMockito.spy(checkGlobalThis);
        PowerMockito.doReturn(true).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(error);
    }

    /**
     * Test Case 4: n.getType() is NOT Token.THIS, but n IS assignLhsChild.
     * Covers: first if fails, second if succeeds (sets assignLhsChild to null).
     */
    @Test
    public void testVisit_ResetAssignLhsChild() {
        when(n.getType()).thenReturn(Token.NAME);

        // Use reflection to set the private field assignLhsChild for testing
        setAssignLhsChild(checkGlobalThis, n);

        checkGlobalThis.visit(t, n, parent);

        assertNull("assignLhsChild should be null after visit", getAssignLhsChild(checkGlobalThis));
    }

    /**
     * Test Case 5: n.getType() is Token.THIS, shouldReportThis is true, AND n IS assignLhsChild.
     * Covers: both if blocks succeed.
     */
    @Test
    public void testVisit_BothConditionsMet() {
        when(n.getType()).thenReturn(Token.THIS);
        when(t.makeError(n, any(), any())).thenReturn(error);
        setAssignLhsChild(checkGlobalThis, n);

        CheckGlobalThis spyCheck = PowerMockito.spy(checkGlobalThis);
        PowerMockito.doReturn(true).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(error);
        assertNull("assignLhsChild should be null", getAssignLhsChild(spyCheck));
    }

    // Helper methods to access private field 'assignLhsChild' via reflection
    private void setAssignLhsChild(CheckGlobalThis instance, Node node) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            field.set(instance, node);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private Node getAssignLhsChild(CheckGlobalThis instance) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            return (Node) field.get(instance);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
